   376|  if (!durable) {
   377|    if (!memoryQueue) memoryQueue = emptyQueue(false);
   378|    return memoryQueue;
   379|  }
   380|  try {
   381|    const doc = await readDurableJson<QueueDoc>(QUEUE_FILE, emptyQueue(true));
   382|    return { ...doc, marker: IVX_SENIOR_DEV_WORKER_MARKER, durable: true };
   383|  } catch {
   384|    if (!memoryQueue) memoryQueue = emptyQueue(false);
