   406|async function loadLedger(): Promise<LedgerDoc> {
   407|  const durable = isDurableStoreConfigured();
   408|  if (!durable) {
   409|    if (memoryLedger && memoryLedger.entries.length > 0) return memoryLedger;
   410|    // Diskless restart fallback: recover the ledger persisted to the GitHub
   411|    // side branch so proof survives Render deploy restarts without Supabase.
   412|    const fromGitHub = await githubLedgerRead();
   413|    if (fromGitHub) {
   414|      memoryLedger = fromGitHub;
   415|      return fromGitHub;
   416|    }
   417|    if (!memoryLedger) memoryLedger = emptyLedger(false);
   418|    return memoryLedger;
   419|  }
   420|  try {
   421|    const doc = await readDurableJson<LedgerDoc>(LEDGER_FILE, emptyLedger(true));
   422|    return { ...doc, marker: IVX_SENIOR_DEV_WORKER_MARKER, durable: true };
   423|  } catch {
   424|    if (!memoryLedger) memoryLedger = emptyLedger(false);
   425|    return memoryLedger;
   426|  }
