   429|// ── GitHub side-branch ledger persistence (no Supabase service key needed) ──
   430|// The ledger is committed to a NON-deploy branch so Render autoDeploy (which
   431|// watches main) never fires from a ledger write. No secrets are stored.
   432|
   433|const LEDGER_GITHUB_BRANCH = 'ivx-proof-ledger';
   434|const DEFAULT_LEDGER_REPO = 'ibb142/ivx-holdings-platform';
   435|
   436|function ledgerGithubToken(): string {
   437|  return typeof process.env.GITHUB_TOKEN === 'string' ? process.env.GITHUB_TOKEN.trim() : '';
   438|}
   439|
   440|function ledgerGithubRepo(): string {
   441|  const raw = typeof process.env.GITHUB_REPO === 'string' ? process.env.GITHUB_REPO.trim() : '';
   442|  const match = raw.match(/([A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+?)(?:\.git)?$/);
   443|  if (match && match[1].includes('/')) return match[1];
   444|  return DEFAULT_LEDGER_REPO;
   445|}
   446|
   447|function ledgerGithubHeaders(): Record<string, string> {
   448|  return {
   449|    Authorization: `Bearer ${ledgerGithubToken()}`,
   450|    Accept: 'application/vnd.github+json',
   451|    'Content-Type': 'application/json',
   452|  };
