   454|
   455|async function githubLedgerRead(): Promise<LedgerDoc | null> {
   456|  const token = ledgerGithubToken();
   457|  if (!token) return null;
   458|  try {
   459|    const res = await fetch(
   460|      `https://api.github.com/repos/${ledgerGithubRepo()}/contents/${LEDGER_FILE}?ref=${LEDGER_GITHUB_BRANCH}`,
   461|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   462|    );
   463|    if (!res.ok) return null;
   464|    const data = await res.json() as { content?: string };
   465|    if (!data.content) return null;
   466|    const decoded = Buffer.from(data.content, 'base64').toString('utf8');
   467|    const doc = JSON.parse(decoded) as LedgerDoc;
   468|    if (!Array.isArray(doc.entries)) return null;
   469|    return { ...doc, marker: IVX_SENIOR_DEV_WORKER_MARKER, durable: true };
   470|  } catch {
   471|    return null;
   472|  }
