   475|async function githubEnsureLedgerBranch(): Promise<boolean> {
   476|  const repo = ledgerGithubRepo();
   477|  try {
   478|    const refRes = await fetch(
   479|      `https://api.github.com/repos/${repo}/git/ref/heads/${LEDGER_GITHUB_BRANCH}`,
   480|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   481|    );
   482|    if (refRes.ok) return true;
   483|    const mainRes = await fetch(
   484|      `https://api.github.com/repos/${repo}/git/ref/heads/main`,
   485|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   486|    );
   487|    if (!mainRes.ok) return false;
   488|    const mainData = await mainRes.json() as { object?: { sha?: string } };
   489|    const baseSha = mainData.object?.sha;
   490|    if (!baseSha) return false;
   491|    const createRes = await fetch(`https://api.github.com/repos/${repo}/git/refs`, {
   492|      method: 'POST',
   493|      headers: ledgerGithubHeaders(),
   494|      body: JSON.stringify({ ref: `refs/heads/${LEDGER_GITHUB_BRANCH}`, sha: baseSha }),
   495|      signal: AbortSignal.timeout(10000),
   496|    });
   497|    return createRes.ok;
   498|  } catch {
   499|    return false;
   500|  }
