   503|async function githubLedgerWrite(doc: LedgerDoc): Promise<boolean> {
   504|  const token = ledgerGithubToken();
   505|  if (!token) return false;
   506|  const repo = ledgerGithubRepo();
   507|  try {
   508|    if (!(await githubEnsureLedgerBranch())) return false;
   509|    let existingSha: string | undefined;
   510|    const currentRes = await fetch(
   511|      `https://api.github.com/repos/${repo}/contents/${LEDGER_FILE}?ref=${LEDGER_GITHUB_BRANCH}`,
   512|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   513|    );
   514|    if (currentRes.ok) {
   515|      const current = await currentRes.json() as { sha?: string };
   516|      existingSha = current.sha;
   517|    }
   518|    const putRes = await fetch(
   519|      `https://api.github.com/repos/${repo}/contents/${LEDGER_FILE}`,
   520|      {
   521|        method: 'PUT',
   522|        headers: ledgerGithubHeaders(),
   523|        body: JSON.stringify({
   524|          message: `chore(ledger): proof ledger update ${nowIso()}`,
   525|          content: Buffer.from(JSON.stringify(doc, null, 2), 'utf8').toString('base64'),
   526|          branch: LEDGER_GITHUB_BRANCH,
   527|          ...(existingSha ? { sha: existingSha } : {}),
   528|        }),
   529|        signal: AbortSignal.timeout(15000),
   530|      },
   531|    );
   532|    return putRes.ok;
   533|  } catch {
   534|    return false;
   535|  }
