   751|/** Map a QA-only runtime phase to a worker job stage. */
   752|function qaPhaseToStage(phase: IVXQAOnlyPhase): { stage: IVXWorkerJobStage; detail: string } {
   753|  switch (phase) {
   754|    case 'queued':
   755|      return { stage: 'QUEUED', detail: 'QA-only run queued.' };
   756|    case 'module_identified':
   757|      return { stage: 'RUNNING', detail: 'Identifying module keywords from goal.' };
   758|    case 'files_inspected':
   759|      return { stage: 'RUNNING', detail: 'Inspecting module source files.' };
   760|    case 'tests_selected':
   761|      return { stage: 'TESTING', detail: 'Selecting test files matching the module.' };
   762|    case 'tests_executed':
   763|      return { stage: 'TESTING', detail: 'Running targeted module tests.' };
   764|    case 'typecheck_run':
   765|      return { stage: 'VERIFYING', detail: 'Running scoped typecheck.' };
   766|    case 'lint_run':
   767|      return { stage: 'VERIFYING', detail: 'Running lint.' };
   768|    case 'completed':
   769|      return { stage: 'COMPLETED', detail: 'QA-only run completed. No files changed, no commit, no deploy.' };
   770|    case 'blocked':
   771|      return { stage: 'FAILED', detail: 'QA-only run blocked (QA_TARGET_NOT_FOUND).' };
   772|    case 'failed':
   773|      return { stage: 'FAILED', detail: 'QA-only run failed.' };
   774|    default:
   775|      return { stage: 'RUNNING', detail: `Phase: ${phase}` };
   776|  }
