   779|/**
   780| * Derive a secret-safe proof summary from an autonomous-coder run proof.
   781| * Same `IVXWorkerJobResult` shape the durable ledger stores, so /senior-proof
   782| * and /senior-ledger surface it the same way. Mutation flags reflect the
   783| * real autonomous-coder outcome (patch applied, commit created, deploy
   784| * triggered, production verified).
   785| */
   786|/**
   787| * Reject stale or incomplete mutation evidence before it can enter the durable
   788| * ledger as a completed code-change or deploy job. A mutation must create a
   789| * commit after its captured starting SHA; a deploy must additionally prove the
   790| * new commit is live. This is intentionally stricter than a health-only check.
   791| */
   792|function autonomousCoderMutationProofError(proof: IVXAutonomousCoderProof): string | null {
   793|  const isMutation = proof.executionMode === 'code_change' || proof.executionMode === 'deploy';
   794|  if (!isMutation || proof.finalStatus !== 'COMPLETED') return null;
   795|  if (proof.filesChanged.length === 0) return 'Code-change job produced no changed files; stale evidence is not accepted.';
   796|  if (!proof.commitSha) return 'Code-change job produced no commit SHA; stale evidence is not accepted.';
   797|  if (proof.startingSha && proof.commitSha === proof.startingSha) return 'Code-change job reused its starting commit SHA; stale evidence is not accepted.';
   798|  if (proof.executionMode === 'deploy') {
   799|    if (proof.branch !== 'main') return `Production deployment commit was rejected because it landed on ${proof.branch ?? 'no branch'}, not the approved production branch main.`;
   800|    if (!proof.deployId) return 'Deploy job produced no Render deployment ID.';
   801|    if (proof.deployStatus !== 'live') return `Deploy job did not reach Render live status (status=${proof.deployStatus ?? 'missing'}).`;
   802|    if (!proof.healthOk || !proof.healthResponse?.ok || proof.healthResponse.commitSha !== proof.commitSha) return 'Deploy job did not verify a healthy production /health response with the requested commit.';
   803|    if (!proof.versionResponse?.ok || proof.versionResponse.commitSha !== proof.commitSha) return 'Deploy job did not verify a production /version response with the requested commit.';
   804|    if (!proof.productionVerified || proof.liveCommit !== proof.commitSha) return 'Deploy job did not verify its new commit in production.';
   805|  }
   806|  return null;
   807|}
   808|
   809|export function summarizeAutonomousCoderProof(
   810|  jobId: string,
   811|  proof: IVXAutonomousCoderProof,
   812|): IVXWorkerJobResult {
   813|  const mutationProofError = autonomousCoderMutationProofError(proof);
   814|  const completed = proof.finalStatus === 'COMPLETED' && mutationProofError === null;
   815|  const finalStatus: IVXWorkerJobResult['finalStatus'] = completed
   816|    ? (proof.commitSha ? 'COMPLETE' : 'LOCAL_ONLY')
   817|    : proof.finalStatus === 'BLOCKED'
   818|      ? 'BLOCKED'
   819|      : 'FAILED';
   820|  return {
   821|    jobId,
   822|    goal: proof.goal.slice(0, 280),
   823|    ok: completed,
   824|    endToEndProductionComplete: completed && proof.productionVerified,
   825|    changedFiles: proof.filesChanged.slice(0, 25),
   826|    testsRun: proof.commandsRun.some((cmd) => /test/i.test(cmd.command)),
   827|    testsPassed: proof.testsPassed,
   828|    typecheckRun: proof.commandsRun.some((cmd) => /tsc|typecheck|noEmit/i.test(cmd.command)),
   829|    typecheckPassed: proof.typecheckPassed,
   830|    buildRun: proof.buildRun,
   831|    commitCreated: Boolean(proof.commitSha),
   832|    commitSha: proof.commitSha,
   833|    commitUrl: proof.commitUrl,
   834|    pushed: Boolean(proof.commitSha),
   835|    branch: proof.branch,
   836|    prNumber: proof.prNumber ?? null,
   837|    prUrl: proof.prUrl ?? null,
   838|    prMerged: proof.prMerged ?? false,
   839|    prMergeCommitSha: proof.prMergeCommitSha ?? null,
   840|    deployId: proof.deployId,
   841|    deployStatus: proof.deployStatus,
   842|    deployVerified: completed && proof.productionVerified,
   843|    deployRequested: proof.deployApproved && completed && Boolean(proof.deployId),
   844|    liveCommit: proof.liveCommit,
   845|    commitMatch: completed && proof.productionVerified && proof.liveCommit === proof.commitSha,
