  1570|        `${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/pulls/${prNumber}/merge`,
  1571|        {
  1572|          method: 'PUT',
  1573|          headers,
  1574|          body: JSON.stringify({
  1575|            commit_title: commitMessage,
  1576|            merge_method: 'squash',
  1577|          }),
  1578|          signal: AbortSignal.timeout(15000),
  1579|        },
  1580|      );
