  1720|// ── PRODUCTION ROLLBACK (Phase 16) ────────────────────────────────────────────
  1721|//
  1722|// When a deploy verifies-fail (health check returns a different commit, or the
  1723|// health endpoint is down after the deploy), the engine attempts an automatic
  1724|// rollback: it fetches the parent of the just-deployed commit, creates a revert
  1725|// commit that restores the prior tree, pushes it to the branch, and re-triggers
  1726|// a Render deploy of the revert commit. This is bounded — one attempt — and any
  1727|// failure is recorded in rollbackError (the engine never silently swallows a
  1728|// rollback failure).
  1729|
  1730|async function getCommitParentSha(owner: string, repo: string, token: string, commitSha: string): Promise<string | null> {
  1731|  try {
  1732|    const res = await fetch(`${GITHUB_API_BASE_URL}/repos/${owner}/${repo}/git/commits/${encodeURIComponent(commitSha)}`, {
  1733|      headers: { Authorization: `Bearer ${token}`, Accept: 'application/vnd.github+json' },
  1734|      signal: AbortSignal.timeout(10000),
  1735|    });
  1736|    if (!res.ok) return null;
  1737|    const data = await res.json() as { parents?: Array<{ sha?: string }> };
  1738|    return data.parents?.[0]?.sha ?? null;
  1739|  } catch { return null; }
  1740|}
  1741|
  1742|async function rollbackProductionDeploy(commitSha: string, branch: string): Promise<{ reverted: boolean; revertCommitSha: string | null; error: string | null }> {
  1743|  const repoUrl = await readOwnerRuntimeVariable('GITHUB_REPO_URL');
  1744|  const token = await readOwnerRuntimeVariable('GITHUB_TOKEN');
  1745|  const repoInfo = parseGithubRepoUrl(repoUrl);
  1746|  if (!repoInfo || !token) return { reverted: false, revertCommitSha: null, error: 'Rollback aborted: GitHub credentials unavailable (checked process.env and owner variables store).' };
  1747|  const headers = { Authorization: `Bearer ${token}`, Accept: 'application/vnd.github+json', 'Content-Type': 'application/json' };
  1748|  // 1. Get the parent of the bad commit (the last known-good SHA).
  1749|  const parentSha = await getCommitParentSha(repoInfo.owner, repoInfo.repo, token, commitSha);
  1750|  if (!parentSha) return { reverted: false, revertCommitSha: null, error: `Could not resolve parent of ${commitSha}.` };
  1751|  // 2. Get the parent commit's tree.
  1752|  let parentTreeSha: string | null = null;
  1753|  try {
  1754|    const res = await fetch(`${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/git/commits/${encodeURIComponent(parentSha)}`, { headers, signal: AbortSignal.timeout(10000) });
  1755|    if (res.ok) {
  1756|      const data = await res.json() as { tree?: { sha?: string } };
  1757|      parentTreeSha = data.tree?.sha ?? null;
  1758|    }
  1759|  } catch { /* fall through */ }
  1760|  if (!parentTreeSha) return { reverted: false, revertCommitSha: null, error: `Could not read parent tree for ${parentSha}.` };
  1761|  // 3. Create a revert commit pointing at the parent's tree (restores prior files).
  1762|  let revertCommitSha: string | null = null;
  1763|  try {
  1764|    const res = await fetch(`${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/git/commits`, {
  1765|      method: 'POST', headers,
  1766|      body: JSON.stringify({ message: `IVX autonomous coder ROLLBACK: revert ${commitSha.slice(0, 7)} (deploy verified-fail)`, tree: parentTreeSha, parents: [parentSha] }),
  1767|      signal: AbortSignal.timeout(15000),
  1768|    });
  1769|    if (res.ok) {
  1770|      const data = await res.json() as { sha?: string };
  1771|      revertCommitSha = data.sha ?? null;
  1772|    }
  1773|  } catch { /* fall through */ }
  1774|  if (!revertCommitSha) return { reverted: false, revertCommitSha: null, error: 'Revert commit creation failed.' };
  1775|  // 4. Update the branch ref to the revert commit (fast-forward to the revert).
  1776|  try {
  1777|    const res = await fetch(`${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/git/refs/heads/${encodeURIComponent(branch)}`, {
  1778|      method: 'PATCH', headers, body: JSON.stringify({ sha: revertCommitSha, force: false }),
  1779|      signal: AbortSignal.timeout(10000),
  1780|    });
  1781|    if (!res.ok) return { reverted: false, revertCommitSha, error: `Branch ref update failed: ${res.status}` };
  1782|  } catch (e) {
  1783|    return { reverted: false, revertCommitSha, error: `Branch ref update threw: ${safeErrorMessage(e)}` };
  1784|  }
  1785|  // 5. Re-trigger Render deploy of the revert commit.
  1786|  try {
  1787|    await triggerRenderDeploy(revertCommitSha);
  1788|  } catch (e) {
  1789|    return { reverted: false, revertCommitSha, error: `Revert commit pushed but redeploy trigger failed: ${safeErrorMessage(e)}` };
  1790|  }
  1791|  return { reverted: true, revertCommitSha, error: null };
  1792|}
