   705|function buildProviderReadiness(rows: OwnerVariableRow[]): Record<OwnerVariableProvider, ProviderReadiness> {
   706|  const rowByName = new Map(rows.map((row) => [row.name, row]));
   707|  const providers = Array.from(new Set(OWNER_VARIABLES.map((item) => item.provider))) as OwnerVariableProvider[];
   708|  return Object.fromEntries(providers.map((provider) => {
   709|    const required = OWNER_VARIABLES.filter((item) => item.provider === provider && item.required).map((item) => item.name);
   710|    // A required variable is satisfied if it's in the encrypted store OR in the backend runtime env.
   711|    const saved = required.filter((name) => rowByName.has(name) || readEnv(name));
   712|    const missing = required.filter((name) => !rowByName.has(name) && !readEnv(name));
   713|    const providerRows = OWNER_VARIABLES.filter((item) => item.provider === provider).map((item) => rowByName.get(item.name)).filter((row): row is OwnerVariableRow => Boolean(row));
   714|    const hasInvalid = providerRows.some((row) => row.status === 'invalid');
   715|    const hasTested = required.length > 0 && required.every((name) => rowByName.get(name)?.status === 'tested');
   716|    const lastTestedAt = providerRows
   717|      .map((row) => row.last_tested_at)
   718|      .filter((value): value is string => Boolean(value))
   719|      .sort()
   720|      .at(-1) ?? null;
   721|    const status: ProviderReadiness['status'] = missing.length > 0 ? 'missing' : hasInvalid ? 'invalid' : hasTested ? 'tested' : 'saved';
   722|    return [provider, {
   723|      provider,
   724|      status,
   725|      requiredVariableNames: required,
   726|      savedVariableNames: saved,
   727|      missingVariableNames: missing,
   728|      lastTestedAt,
   729|      secretValuesReturned: false as const,
   730|    }];
   731|  })) as Record<OwnerVariableProvider, ProviderReadiness>;
